/* From Uiverse.io by KhaledMatalkah - Tags: checkbox, flip, transition, cool checkbox */
.__UIV_SCOPE__ .custom-checkbox {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
  font-size: 16px;
  color: #333;
  transition: color 0.3s;
}

.__UIV_SCOPE__ .custom-checkbox input[type="checkbox"] {
  display: none;
}

.__UIV_SCOPE__ .custom-checkbox .checkmark {
  width: 24px;
  height: 24px;
  border: 2px solid #333;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 10px;
  transition: background-color 0.3s, border-color 0.3s, transform 0.3s;
  transform-style: preserve-3d;
}

.__UIV_SCOPE__ .custom-checkbox .checkmark::before {
  content: "\2713";
  font-size: 16px;
  color: transparent;
  transition: color 0.3s, transform 0.3s;
}

.__UIV_SCOPE__ .custom-checkbox input[type="checkbox"]:checked + .checkmark {
  background-color: #333;
  border-color: #333;
  transform: scale(1.1) rotateZ(360deg) rotateY(360deg);
}

.__UIV_SCOPE__ .custom-checkbox input[type="checkbox"]:checked + .checkmark::before {
  color: #fff;
}

.__UIV_SCOPE__ .custom-checkbox:hover {
  color: #666;
}

.__UIV_SCOPE__ .custom-checkbox:hover .checkmark {
  border-color: #666;
  background-color: #f0f0f0;
  transform: scale(1.05);
}

.__UIV_SCOPE__ .custom-checkbox input[type="checkbox"]:focus + .checkmark {
  box-shadow: 0 0 3px 2px rgba(0, 0, 0, 0.2);
  outline: none;
}

.__UIV_SCOPE__ .custom-checkbox .checkmark,
.__UIV_SCOPE__ .custom-checkbox input[type="checkbox"]:checked + .checkmark {
  transition: background-color 1.3s, border-color 1.3s, color 1.3s, transform 0.3s;
}
